-- Monetisation, lot B (21 November 2026): the subscription summary stays true without any event, and a purchase Google may still turn
-- into access is never left unread.
-- 1. profiles.is_elite was only recomputed when an event reached the account. With a lost notification and the hourly Google sweep off
--    (PLAY_BILLING_ENABLED unset, an outage), an ended subscription kept is_elite = true for ever: the server gates already compare
--    elite_ends_at, but the Android ads gate, the offers screen (which then refused a new subscription) and the coach capacity summary
--    read the flag. An hourly sweep recomputes, with the existing rule (titan_entitlement_refresh_profile), the accounts whose flag says
--    "access" while no source of theirs is eligible any more. Offered accesses without an end date stay eligible: nothing granted on
--    purpose is removed. Accounts without any ledger row are left alone, as in 20261110130137.
-- 2. The Google sweep (titan_play_entitlements_due_v1) only named ACTIVE rows. A purchase recorded while pending, on account hold or
--    paused becomes active later on Google's side; if that notification is lost the player paid without access until they reopen the
--    app. Such rows are now re-read every six hours; Google ends those states by itself (hold 60 days, pause 3 months), so the list
--    empties on its own. Google's answer still decides; nothing is granted to a token the ledger does not know.
-- 3. The product → plan mapping (private.titan_plan_products) existed only in production, set by hand: a replica, a new environment or
--    a rebuilt project sold Coach without any seat. The three products of the specification are seeded; an existing mapping is kept.
-- Additive. The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: select cron.unschedule('titan_entitlements_expiry_sweep'); drop function public.titan_entitlements_expiry_sweep_v1(),
-- private.titan_entitlements_expiry_sweep(integer); re-apply titan_play_entitlements_due_v1 of 20261110152900; the seeded mapping rows
-- are identical to production's and can stay.

create or replace function private.titan_entitlements_expiry_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_uid uuid;
  v_n integer := 0;
begin
  for v_uid in
    select p.id
      from public.profiles p
     where p.is_elite is true
       and exists (select 1 from private.titan_entitlements e where e.user_id = p.id)
       and not exists (select 1 from private.titan_entitlements e
                        where e.user_id = p.id and e.is_active and e.refunded_at is null and (e.ends_at is null or e.ends_at > now()))
     order by p.id
     limit least(greatest(coalesce(p_limit, 500), 1), 5000)
  loop
    -- Same per-account lock as every billing writer: a concurrent purchase or renewal is never overwritten by the sweep.
    perform pg_advisory_xact_lock(hashtextextended('titan_entitlement:' || v_uid::text, 0));
    perform private.titan_entitlement_refresh_profile(v_uid);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$function$;
revoke all on function private.titan_entitlements_expiry_sweep(integer) from public, anon, authenticated;

create or replace function public.titan_entitlements_expiry_sweep_v1()
returns integer
language sql
security definer
set search_path = ''
as $function$ select private.titan_entitlements_expiry_sweep(500); $function$;
revoke all on function public.titan_entitlements_expiry_sweep_v1() from public, anon, authenticated;
grant execute on function public.titan_entitlements_expiry_sweep_v1() to service_role;

do $$
begin
  -- pg_cron exists in production, not on the local bench.
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    return;
  end if;
  if not exists (select 1 from cron.job where jobname = 'titan_entitlements_expiry_sweep') then
    perform cron.schedule('titan_entitlements_expiry_sweep', '23 * * * *', 'select public.titan_entitlements_expiry_sweep_v1();');
  end if;
end $$;

create or replace function public.titan_play_entitlements_due_v1(p_limit integer default 50)
returns table (user_id uuid, external_id text)
language sql stable security definer set search_path = ''
as $function$
  select e.user_id, e.external_id
  from private.titan_entitlements e
  where e.source = 'google_play'
    and ((e.is_active and (e.provider_needs_ack
           or coalesce(e.ends_at, e.last_event_at) < now() + interval '1 day'
           or e.last_event_at < now() - interval '3 days'))
      -- A state Google may still turn into access (pending payment, account hold, pause): re-read every six hours.
      or (not e.is_active and e.status in ('pending', 'on_hold', 'paused') and e.last_event_at < now() - interval '6 hours'))
  order by e.provider_needs_ack desc, e.is_active desc, e.last_event_at asc
  limit least(greatest(coalesce(p_limit, 50), 1), 200);
$function$;
revoke all on function public.titan_play_entitlements_due_v1(integer) from public, anon, authenticated;
grant execute on function public.titan_play_entitlements_due_v1(integer) to service_role;

insert into private.titan_plan_products (product_id, plan)
values ('titan01', 'titan_plus'), ('titan02', 'coach'), ('titan03', 'coach_pro')
on conflict (product_id) do nothing;

